export function brickHit(ball, bricks, prevX = ball.px ?? ball.x, prevY = ball.py ?? ball.y) {
  const destroyed = [];

  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const dist = Math.hypot(dx, dy);
  const steps = Math.max(1, Math.ceil(dist / BRICK_H));

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const sx = prevX + dx * t;
    const sy = prevY + dy * t;
    const probe = { x: sx, y: sy, r: ball.r };

    const hit = bricks.filter((b) => b.alive && collides(probe, b));
    if (hit.length === 0) continue;

    for (const brick of hit) {
      brick.alive = false;
      destroyed.push(brick);
    }
    resolveBounce(ball, probe, hit);
    break;
  }

  return destroyed;
}
```

