```js
// --- Brick collision (pure, testable) --------------------------------------

// Resolves the ball against the bricks for one frame's move, including the
// bounce the frame() loop used to skip (see ISSUES.md #1).
//
// The ball swept from (ball.px, ball.py) — its position before the move — to
// its current (ball.x, ball.y). The segment is sampled at most BRICK_H px
// apart, so a fast ball cannot tunnel through a brick between two frames: at
// level 6 a capped 50 ms frame moves the ball 35.5 px, more than the 34 px
// (BRICK_H + diameter) it takes to cross a brick.
//
// Every brick the swept ball touches is destroyed and returned (the caller
// scores them). Then the ball receives exactly ONE bounce, resolved against
// the union of the destroyed bricks:
//   - the axis with the smaller penetration is the face that was hit: flip
//     vy on a top/bottom hit, vx on a side hit, leave the other component
//     alone;
//   - equal penetrations mean a diagonal corner hit: flip both components;
//   - the ball is pushed clear of the union on the hit side, so it cannot
//     still overlap the bricks next frame (sticky bounce).
// Resolving against the union means a seam overlap (the 8 px grid gap is
// narrower than the 14 px ball) bounces the ball exactly once.
export function brickHit(ball, bricks, prevX = ball.px ?? ball.x, prevY = ball.py ?? ball.y) {
  const destroyed = [];

  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const dist = Math.hypot(dx, dy);
  const steps = Math.max(1, Math.ceil(dist / BRICK_H));

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const sx = prevX + dx * t;
    const sy = prevY + dy * t;
    const probe = { x: sx, y: sy, r: ball.r };

    const hit = bricks.filter((b) => b.alive && collides(probe, b));
    if (hit.length === 0) continue;

    for (const brick of hit) {
      brick.alive = false;
      destroyed.push(brick);
    }

    resolveBounce(ball, probe, hit);
    break;
  }

  return destroyed;
}

// Bounces `ball` once against the union of the `hit` bricks and pushes it out.
function resolveBounce(ball, probe, hit) {
  let left = Infinity;
  let top = Infinity;
  let right = -Infinity;
  let bottom = -Infinity;
  for (const b of hit) {
    left = Math.min(left, b.x);
    top = Math.min(top, b.y);
    right = Math.max(right, b.x + b.w);
    bottom = Math.max(bottom, b.y + b.h);
  }

  // The ball stands where the sweep found it; move it there first so the
  // push-out below starts from the collision point, not the post-move spot.
  ball.x = probe.x;
  ball.y = probe.y;

  const penX = Math.min(probe.x + probe.r - left, right + probe.r - probe.x);
  const penY = Math.min(probe.y + probe.r - top, bottom + probe.r - probe.y);
  const corner = Math.abs(penX - penY) < 1e-9;

  if (corner || penX < penY) {
    ball.vx = -ball.vx;
    ball.x = probe.x < left + (right - left) / 2 ? left - ball.r : right + ball.r;
  }
  if (corner || penY < penX) {
    ball.vy = -ball.vy;
    ball.y = probe.y < top + (bottom - top) / 2 ? top - ball.r : bottom + ball.r;
  }
}
```

