} from './neon.js';

edits.newText:
// --- #1: brick bounce (issue #1) -------------------------------------------

// A single live brick at the default grid position.
function brickAt(x = 90, y = 90) {
  return { x, y, w: BRICK_W, h: BRICK_H, alive: true, row: 0, points: 50 };
}

test('#1: top face hit flips vy, leaves vx, pushes the ball above the brick', () => {
  const brick = brickAt();
  const ball = { x: 100, y: 85, r: 7, vx: 30, vy: -200 }; // bottom 2 px into the brick
  brickHit(ball, [brick]);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, 200, 'vy should flip to DOWN');
  assert.equal(ball.vx, 30, 'vx must be left exactly as it was');
  assert.equal(ball.y, brick.y - ball.r, 'ball pushed out above the brick');
  assert.equal(collides(ball, brick), false);
});

test('#1: bottom face hit flips vy, leaves vx, pushes the ball below the brick', () => {
  const brick = brickAt();
  const ball = { x: 100, y: 115, r: 7, vx: 25, vy: -300 }; // climbing into the brick
  brickHit(ball, [brick]);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, 300, 'vy should flip to DOWN');
  assert.equal(ball.vx, 25, 'vx must be left exactly as it was');
  assert.equal(ball.y, brick.y + brick.h + ball.r, 'ball pushed out below the brick');
  assert.equal(collides(ball, brick), false);
});

test('#1: side face hit flips vx, leaves vy, pushes the ball out of the side', () => {
  const brick = brickAt();
  const ball = { x: 85, y: 100, r: 7, vx: 300, vy: -40 }; // 2 px into the left face
  brickHit(ball, [brick]);
  assert.equal(brick.alive, false);
  assert.equal(ball.vx, -300, 'vx should flip LEFT');
  assert.equal(ball.vy, -40, 'vy must be left exactly as it was');
  assert.equal(ball.x, brick.x - ball.r, 'ball pushed out to the left');
  assert.equal(collides(ball, brick), false);
});

test('#1: equal penetration on a corner flips both components', () => {
  const brick = brickAt();
  const ball = { x: 84, y: 84, r: 7, vx: 300, vy: -200 }; // 1 px into both faces
  brickHit(ball, [brick]);
  assert.equal(brick.alive, false);
  assert.equal(ball.vx, -300, 'vx should flip LEFT');
  assert.equal(ball.vy, 200, 'vy should flip DOWN');
  assert.equal(ball.x, brick.x - ball.r, 'ball pushed out to the left');
  assert.equal(ball.y, brick.y - ball.r, 'ball pushed out above the brick');
  assert.equal(collides(ball, brick), false);
});

test('#1: seam over two bricks bounces exactly once (no cancelled double flip)', () => {
  const left = brickAt(90, 90);
  const right = brickAt(90 + BRICK_W + BRICK_GAP, 90);
  const seamX = left.x + left.w + BRICK_GAP / 2; // ball centred on the 8 px seam
  const ball = { x: seamX, y: 85, r: 7, vx: 0, vy: -200 }; // overlaps BOTH bricks
  brickHit(ball, [left, right]);
  assert.equal(left.alive, false);
  assert.equal(right.alive, false);
  assert.equal(ball.vy, 200, 'flipped exactly once — a double flip would cancel out');
  assert.equal(ball.vx, 0, 'side component untouched');
  assert.equal(ball.y, left.y - ball.r, 'ball pushed out above the seam');
  assert.equal(collides(ball, left), false);
  assert.equal(collides(ball, right), false);
});

test('#1: sweep catches a ball tunnelling through a brick in one stuttered step', () => {
  const brick = brickAt();
  // ballSpeed(6) = 710 px/s, frame capped at 50 ms => 35.5 px per step, more
  // than the 34 px (BRICK_H + diameter) it takes to cross a brick.
  const move = ballSpeed(6) * 0.05;
  const ball = { x: 100, y: brick.y - 7, r: 7, vx: 0, vy: ballSpeed(6) };
  ball.px = ball.x;
  ball.py = ball.y;
  ball.y += move; // now fully past the brick: a discrete check would miss it
  assert.equal(collides(ball, brick), false, 'static overlap must miss the tunnel');
  const hit = brickHit(ball, [brick]);
  assert.equal(hit.length, 1);
